/**
 * The authoring catalog — single source of truth for product copy (EN + AR).
 *
 * The SERVER imports this module directly (siteStringsService, CMS routes,
 * integrity scripts): it wants both languages. The CLIENT must not: before
 * the per-language split, shipping this whole object put both languages in
 * front of first paint (~50% avoidable dictionary bytes for every first-time
 * visitor). Client code therefore goes through src/i18n/translator.ts, which
 * lazy-loads only the active language from the generated chunks in
 * dictionaries/ (refresh with `npm run i18n:emit`; a drift gate fails the
 * suite when they are stale), and tests/domain/i18nDictionarySync.test.ts
 * FAILS if any src/ module imports this file — one value-level reference
 * would pin the whole catalog back into the importing chunk.
 *
 * translate() below keeps the compiled-catalog resolution for every
 * non-client consumer (the server, tests of the catalog itself). Client
 * resolution never touches it: LanguageContext resolves through the
 * registry, and src/lib/authErrorMessages.ts resolves via its own registry
 * view seed (tests/i18nSeed.ts).
 *
 * Copy edits stay here. Interpolation and fallback semantics live in
 * resolve.ts so the compiled path and the registry path cannot drift.
 */
import {
  interpolateText,
  type DictView,
  type Language,
  type TVars,
} from './resolve';

// Canonical types live in resolve.ts (so client modules can import them
// without touching this catalog); re-exported here so the many existing
// type-only Language/TVars importers keep compiling.
export type { Language, TVars };

export interface Translations {
  [key: string]: {
    en: string;
    ar: string;
  };
}

export function translate(
  key: string,
  language: Language,
  vars?: TVars,
  fallback?: string
): string {
  const entry = TRANSLATIONS[key];
  const interpolateIfVars = (text: string) => (vars ? interpolateText(text, vars) : text);
  if (entry && entry[language]) return interpolateIfVars(entry[language]);
  if (entry) return interpolateIfVars(entry.en);
  if (import.meta.env.DEV) console.warn(`[i18n] missing translation key: ${key}`);
  return fallback ?? key;
}

