  // checkout contract: hold-then-pay errors, cancellation deadline, driver assignment
  "checkout.error.priceChanged": { en: "The price changed since you started. It's now {amount} — want to go ahead?", ar: "السعر اتغيّر من ساعة ما بدأت. السعر الجديد {amount}، تحب تكمّل؟" },
  "checkout.error.priceChangedNoAmount": { en: "The price changed since you started. Pick your slot again to see the new price — nothing was charged.", ar: "السعر اتغيّر من ساعة ما بدأت. اختار ميعادك تاني عشان تشوف السعر الجديد، ومفيش فلوس اتخصمت." },
  "checkout.error.holdExpired": { en: "Your reserved spot timed out before we could confirm it. Nothing was charged — want us to hold it again?", ar: "الحجز المؤقت خلص وقته قبل ما نأكّده. مفيش فلوس اتخصمت، تحب نحجزهولك تاني؟" },
  "checkout.error.holdRequired": { en: "We need to hold your spot before you pay. Let's reserve it again.", ar: "لازم نحجزلك مكانك الأول قبل الدفع. يلا نحجزه تاني." },
  "checkout.error.holdMismatch": { en: "Your booking details changed after we held your spot. Let's hold it again with the new details.", ar: "تفاصيل الحجز اتغيّرت بعد ما حجزنالك المكان. نحجزه تاني بالتفاصيل الجديدة؟" },
  "checkout.error.holdNotOwned": { en: "This reservation belongs to a different account. Sign in again and we'll start fresh.", ar: "الحجز ده متسجّل على حساب تاني. سجّل دخولك تاني ونبدأ من الأول." },
  "checkout.error.supplierUnavailable": { en: "This provider isn't taking bookings right now. Nothing was charged — have a look at a few similar options.", ar: "المزوّد ده مش بياخد حجوزات دلوقتي. مفيش فلوس اتخصمت، بص على اختيارات قريبة منه." },
  "checkout.error.fraudBlocked": { en: "We couldn't complete this payment for security reasons. Nothing was charged — our team can help you finish the booking.", ar: "معرفناش نكمّل الدفع ده لأسباب أمان. مفيش فلوس اتخصمت، وفريقنا يقدر يساعدك تكمّل الحجز." },
  "checkout.error.soldOut": { en: "That time just filled up. Pick another time or see similar options.", ar: "الميعاد ده اتملى. اختار وقت تاني أو بص على اختيارات شبهه." },
  "checkout.error.dateBlocked": { en: "The provider is closed on {date}. Try another date.", ar: "المزوّد قافل يوم {date}. جرّب يوم تاني." },
  "checkout.error.dateBlockedNoDate": { en: "The provider is closed that day. Try another date.", ar: "المزوّد قافل اليوم ده. جرّب يوم تاني." },
  "checkout.error.signIn": { en: "Sign in to finish your booking — your choices are saved.", ar: "سجّل دخولك عشان تكمّل الحجز، اختياراتك محفوظة." },
  "checkout.error.forbidden": { en: "Your account can't make this booking. Get in touch and we'll sort it out.", ar: "حسابك مش مسموحله يعمل الحجز ده. كلّمنا ونحلّها." },
  "checkout.error.rateLimited": { en: "That was a lot of tries in a short time. Wait a minute and try again.", ar: "محاولات كتير ورا بعض. استنى دقيقة وجرّب تاني." },
  "checkout.error.server": { en: "Something went wrong on our side. Nothing was charged — try again in a moment.", ar: "حصلت مشكلة عندنا. مفيش فلوس اتخصمت، جرّب تاني كمان شوية." },
  "checkout.error.network": { en: "We couldn't reach the server. Check your connection — nothing was charged.", ar: "مش قادرين نوصل للسيرفر. اتأكد من النت، ومفيش فلوس اتخصمت." },
  "checkout.error.unknown": { en: "We couldn't finish the booking. Nothing was charged — please try again.", ar: "معرفناش نكمّل الحجز. مفيش فلوس اتخصمت، جرّب تاني." },
  // A bare schema 400 the server answered with no code: the missing request
  // field is named so the traveler can complete it instead of retrying blind.
  "checkout.error.requiredField": { en: "A required booking detail is missing ({field}). Complete the form and try again.", ar: "معلومة مطلوبة للحجز ناقصة ({field}). كمّل البيانات وحاول تاني." },
  "checkout.error.requiredPhone": { en: "The provider needs your mobile number to arrange this — add it above and try again.", ar: "المزود محتاج رقم موبايلك ينفذ ده — ضيفه فوق وحاول تاني." },
  "checkout.error.killSwitch": { en: "Bookings are temporarily switched off by the operations team. Nothing was charged — please try again later.", ar: "الحجوزات متوقفة مؤقتاً من فريق التشغيل. مفيش فلوس اتخصمت، جرّب تاني بعد شوية." },
  "checkout.error.noTrip": { en: "We couldn't find your trip. Go back to your plan and try again — nothing was charged.", ar: "مش لاقيين رحلتك. ارجع لخطتك وجرّب تاني، ومفيش فلوس اتخصمت." },
