// ============================================================================
// Precomputed per-language views (in-module, build-time evaluated)
// ============================================================================
//
// Two jobs:
//
// 1. THE DRIFT GATE'S SEMANTIC SOURCE. scripts/i18n/emitDictionaries.ts and
//    tests/domain/i18nDictionarySync.test.ts compare the generated
//    dictionaries/en|ar.ts against these views key-for-key and
//    value-for-value — the generated chunks can only drift if the drift is
//    visible here too.
//
// 2. THE SERVER'S RESOLUTION VIEW. translate() above is the compiled-catalog
//    entry point for the server and tests; resolving through a flat
//    key→string view (instead of entry[language] probes) keeps the exact same
//    semantics with one code path in resolve.ts. Built once at module load —
//    cheaper per call than per-call property probing, and the objects live
//    here in the catalog either way (they are views, not copies; the data is
//    not duplicated).
export const EN_VIEW: DictView = Object.fromEntries(
  Object.entries(TRANSLATIONS).map(([key, value]) => [key, value.en])
);
export const AR_VIEW: DictView = Object.fromEntries(
  Object.entries(TRANSLATIONS).map(([key, value]) => [key, value.ar])
);

